using System;using System.IO;using LumaDesk;
class TransportChecks {static void Main(){string server="http://127.0.0.1:8765";string name="test"+Guid.NewGuid().ToString("N").Substring(0,12);var login=CloudApi.Send<CloudSession>(server,"POST","/v1/auth/register",new {username=name,password="local-integration-test-password",device_id="transporttest"},null);if(login.user_id<=0||string.IsNullOrEmpty(login.token))throw new Exception("registration failed");var empty=CloudApi.Send<CloudSnapshot>(server,"GET","/v1/sync",null,login.token);if(empty.revision!=0)throw new Exception("initial revision");var doc=CloudJson.New().Deserialize<CloudDocument>(File.ReadAllText("cloud-document-fixture.json"));var saved=CloudApi.Send<CloudSnapshot>(server,"PUT","/v1/sync",new CloudWrite{expected_revision=0,document=doc},login.token);if(saved.revision!=1||saved.document.items[0].Title!="Русское напоминание"||saved.document.items[0].Sound!="@orbit")throw new Exception("JSON boundary");if(saved.document.notes.Count!=1||saved.document.notes[0].Body!="Строка 1\nСтрока 2 — заметка")throw new Exception("Notes JSON boundary");var stale=CloudJson.Copy(doc);stale.items[0].Title="new";try{CloudApi.Send<CloudSnapshot>(server,"PUT","/v1/sync",new CloudWrite{expected_revision=0,document=stale},login.token);throw new Exception("conflict accepted");}catch(CloudApiException e){if(e.Code!=409)throw;}try{CloudApi.Send<CloudSnapshot>(server,"GET","/v1/sync/",null,login.token);throw new Exception("redirect followed");}catch(CloudApiException e){if(e.Code!=307)throw;}CloudApi.Send<object>(server,"POST","/v1/auth/logout",null,login.token);try{CloudApi.Send<CloudSnapshot>(server,"GET","/v1/sync",null,login.token);throw new Exception("session not revoked");}catch(CloudApiException e){if(e.Code!=401)throw;}Console.WriteLine("PASS actual C# HTTP transport: register, bearer auth, Unicode JSON, revision conflict, redirect refusal and logout");}}
